"""Validate vendor feed certificates against the bundled certificate pins."""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
from typing import Mapping


# Pins are represented as lowercase, unseparated SHA-256 digests.  Keeping the
# representation independent of OpenSSL makes checking work for DER supplied by
# either an ssl socket or a certificate store.
_DEFAULT_PINS: Mapping[str, frozenset[str]] = {
    "feeds.tessaro.net": frozenset(
        {"3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"}
    )
}


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER certificate.

    The input is intentionally treated as bytes rather than parsed as an X.509
    object: certificate pinning authenticates the exact certificate bytes and
    this also allows callers to use DER returned by different TLS libraries.
    """
    if not isinstance(cert_der, bytes):
        raise TypeError("cert_der must be bytes")
    return hashlib.sha256(cert_der).hexdigest()


def _normalise_host(host: str) -> str:
    if not isinstance(host, str):
        raise TypeError("host must be str")
    # DNS names are case-insensitive. A trailing dot is an equivalent absolute
    # DNS spelling, but an empty host is never a valid pin lookup.
    return host.rstrip(".").lower()


def _pins_from_environment() -> Mapping[str, frozenset[str]]:
    """Load optional deployment pins from ``CERTPIN_PINS``.

    The variable may contain either a JSON object mapping host names to one
    fingerprint (or a list of fingerprints), or a path to such a JSON file.
    This is useful for rotating pins without changing application code.
    Invalid configuration is rejected rather than silently disabling pinning.
    """
    value = os.environ.get("CERTPIN_PINS")
    if not value:
        return _DEFAULT_PINS
    source = Path(value)
    raw = json.loads(source.read_text() if source.is_file() else value)
    if not isinstance(raw, dict):
        raise ValueError("CERTPIN_PINS must describe a JSON object")
    result: dict[str, frozenset[str]] = {}
    for host, pins in raw.items():
        if isinstance(pins, str):
            pins = [pins]
        if not isinstance(host, str) or not isinstance(pins, list) or not all(
            isinstance(pin, str) for pin in pins
        ):
            raise ValueError("each pin entry must be a host and string/list of strings")
        result[_normalise_host(host)] = frozenset(
            pin.replace(":", "").replace(" ", "").lower() for pin in pins
        )
    return result


def check_pin(cert_der: bytes, host: str) -> bool:
    """Return ``True`` when *cert_der* is pinned for *host*.

    Unknown hosts and malformed pin configuration fail closed. Type errors in
    the caller's arguments are allowed to surface so programming mistakes are
    not mistaken for an authentication failure.
    """
    name = _normalise_host(host)
    digest = fingerprint(cert_der)
    return digest in _pins_from_environment().get(name, frozenset())
